$meals=['Breakfast'=>'08:00-09:00','Morning Snack'=>'10:30-11:00','Lunch'=>'12:00-13:00','Evening Snack'=>'16:30-17:00','During Duty'=>'20:00-21:00','Dinner'=>'22:15-22:45'];
function displayDate(string $iso):string{$t=strtotime($iso);return $t?date('d-m-Y',$t):$iso;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0f172a"><title>Edit Food Entry</title><link rel="stylesheet" href="assets/app.css"></head><body><main class="container"><a class="top" href="index.php">← Back to Dashboard</a><section class="card"><div class="head"><div><h2>✏️ Edit Food Entry</h2><small>Update details without losing your history.</small></div></div><form method="post" action="update.php"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><input type="hidden" name="id" value="<?=h((string)$item['id'])?>"><div class="grid"><div><label>Date</label><input id="date_display" value="<?=h(displayDate($item['lunch_date']))?>" maxlength="10" inputmode="numeric" required><input type="hidden" name="lunch_date" id="lunch_date" value="<?=h($item['lunch_date'])?>"></div><div><label>Meal</label><select name="meal_type"><?php foreach($meals as $name=>$time):?><option value="<?=h($name)?>" <?=$item['meal_type']===$name?'selected':''?>><?=h($name)?></option><?php endforeach;?></select></div><div class="full"><label>Food Item</label><input name="food_item" maxlength="150" value="<?=h($item['food_item'])?>" required></div><div><label>Quantity</label><input name="quantity" maxlength="80" value="<?=h($item['quantity']??'')?>"></div><div><label>Notes</label><input name="notes" maxlength="250" value="<?=h($item['notes']??'')?>"></div><div><label>Calories (kcal)</label><input type="number" name="calories" min="0" max="10000" step="0.1" value="<?=h((string)($item['calories']??0))?>"></div><div><label>Protein (g)</label><input type="number" name="protein" min="0" max="1000" step="0.1" value="<?=h((string)($item['protein']??0))?>"></div><div><label>Carbs (g)</label><input type="number" name="carbs" min="0" max="1000" step="0.1" value="<?=h((string)($item['carbs']??0))?>"></div><div><label>Fat (g)</label><input type="number" name="fat" min="0" max="1000" step="0.1" value="<?=h((string)($item['fat']??0))?>"></div></div><button class="save">Save Changes</button></form></section></main><script>document.querySelector('form').addEventListener('submit',e=>{const m=document.getElementById('date_display').value.trim().match(/^(\d{2})-(\d{2})-(\d{4})$/);if(!m){e.preventDefault();alert('Use DD-MM-YYYY format.');return}const x=new Date(Date.UTC(+m[3],+m[2]-1,+m[1]));if(x.getUTCFullYear()!=+m[3]||x.getUTCMonth()!=+m[2]-1||x.getUTCDate()!=+m[1]){e.preventDefault();alert('Invalid date.');return}document.getElementById('lunch_date').value=m[3]+'-'+m[2]+'-'+m[1]});</script></body></html>
